  confunde:[{id:"comprehend", dif:"Comprehend entende o significado de um texto; Textract tira o texto e a estrutura do documento."},
            {id:"rekognition", dif:"Rekognition entende cenas, rostos e objetos; Textract é especialista em documentos."},
            {id:"transcribe", dif:"Transcribe tira texto de áudio; Textract tira texto de imagens de documentos."}],
  chave:["extrair texto de documentos","OCR","formulários e tabelas","documentos digitalizados","notas fiscais"],
  preco:"Paga por página processada, com valores diferentes para texto simples, formulários, tabelas e consultas.",
